import{_ as n,c as i,o as e,ae as s}from"./chunks/framework.BlRNOFgT.js";const k=JSON.parse('{"title":"Latihan Soal: Microservices Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/microservices.md","filePath":"WBD/microservices.md"}'),t={name:"WBD/microservices.md"};function l(r,a,o,u,g,m){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="latihan-soal-microservices-architecture" tabindex="-1">Latihan Soal: Microservices Architecture <a class="header-anchor" href="#latihan-soal-microservices-architecture" aria-label="Permalink to &quot;Latihan Soal: Microservices Architecture&quot;">​</a></h1><h2 id="bagian-1-konsep-fundamental-definisi" tabindex="-1">Bagian 1: Konsep Fundamental &amp; Definisi <a class="header-anchor" href="#bagian-1-konsep-fundamental-definisi" aria-label="Permalink to &quot;Bagian 1: Konsep Fundamental &amp; Definisi&quot;">​</a></h2><p><strong>1. Manakah pernyataan di bawah ini yang secara akurat mendefinisikan karakteristik utama dari Microservices dalam konteks pemodelan domain?</strong></p><ul><li>A. Microservices memprioritaskan kohesi fungsionalitas teknis (technical functionality) di atas fungsionalitas bisnis.</li><li>B. Microservices adalah layanan yang dapat dirilis secara independen (independently releasable).</li><li>C. Setiap layanan dimodelkan di sekitar domain bisnis (business domain).</li><li>D. Microservices mewajibkan penggunaan satu database terpusat untuk menjamin konsistensi data antar layanan.</li><li>E. Arsitektur ini adalah pilihan spesifik dari pendekatan SOA (Service-Oriented Architecture).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Microservices dimodelkan berdasarkan domain bisnis, dapat dirilis independen, dan merupakan pendekatan spesifik dari SOA.</li><li><strong>Salah (A):</strong> Dokumen menyebutkan sebaliknya: &quot;prioritize high cohesion of business functionality over high cohesion of technical functionality&quot;.</li><li><strong>Salah (D):</strong> Microservices harus memiliki state sendiri (&quot;Owning Their Own State&quot;) dan menghindari database bersama.</li></ul></details><hr><p><strong>2. Terkait konsep Information Hiding dalam Microservices, manakah praktik yang dianggap valid?</strong></p><ul><li>A. Memperlakukan setiap microservice sebagai black box dari sudut pandang eksternal.</li><li>B. Mengekspos detail implementasi internal agar konsumen layanan dapat melakukan optimasi query.</li><li>C. Menyembunyikan informasi sebanyak mungkin di dalam komponen.</li><li>D. Memisahkan fungsionalitas yang sering berubah (internal) dari kontrak eksternal yang jarang berubah.</li><li>E. Mengizinkan layanan lain mengakses tabel database internal secara langsung (read-only) untuk performa.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Konsep utamanya adalah menyembunyikan detail internal (black box) dan hanya mengekspos kontrak eksternal.</li><li><strong>Salah (B &amp; E):</strong> Information hiding justru melarang eksposur implementasi internal atau akses database langsung antar layanan (shared database).</li></ul></details><hr><p><strong>3. Apa implikasi dari prinsip Independent Deployability?</strong></p><ul><li>A. Kita dapat mengubah satu layanan dan merilisnya ke pengguna tanpa harus menyebarkan (deploy) layanan lain.</li><li>B. Layanan harus tightly coupled untuk memastikan integritas rilis.</li><li>C. Perubahan pada satu layanan tidak boleh memaksa perubahan pada layanan lain (loosely coupled).</li><li>D. Semua microservices dalam satu ekosistem harus menggunakan versi bahasa pemrograman yang sama.</li><li>E. Deployment harus dilakukan secara serentak (bulk release) untuk fitur yang melintasi banyak layanan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Kunci independensi adalah loose coupling agar satu layanan bisa di-deploy tanpa memengaruhi yang lain.</li><li><strong>Salah (B):</strong> Seharusnya loosely coupled.</li><li><strong>Salah (D):</strong> Tidak ada syarat keseragaman bahasa (Tech Heterogeneity adalah keuntungan).</li><li><strong>Salah (E):</strong> Ini adalah ciri khas Distributed Monolith, bukan Microservices yang ideal.</li></ul></details><hr><p><strong>4. Mengenai ukuran (Size) sebuah Microservice, manakah parameter yang disarankan?</strong></p><ul><li>A. Ukurannya harus sekecil mungkin, idealnya di bawah 100 baris kode.</li><li>B. Ukurannya dibatasi oleh kemampuan kognitif pengembang (&quot;fit in my head&quot;).</li><li>C. Ukuran ditentukan agar mudah dipahami.</li><li>D. Ukuran harus seragam antar semua layanan dalam sistem.</li><li>E. Kata &quot;micro&quot; menyiratkan batasan fisik memori yang ketat pada perangkat keras.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Dokumen mengutip James Lewis, &quot;as big as my head&quot;, yang rasionalnya adalah agar mudah dipahami.</li><li><strong>Salah (A &amp; D):</strong> Dokumen secara eksplisit menolak pengukuran berbasis jumlah baris kode (LOC) atau keseragaman kaku.</li><li><strong>Salah (E):</strong> &quot;Micro&quot; merujuk pada cakupan fungsionalitas, bukan batasan hardware.</li></ul></details><hr><h2 id="bagian-2-monolith-vs-microservices" tabindex="-1">Bagian 2: Monolith vs Microservices <a class="header-anchor" href="#bagian-2-monolith-vs-microservices" aria-label="Permalink to &quot;Bagian 2: Monolith vs Microservices&quot;">​</a></h2><p><strong>5. Identifikasi pernyataan yang benar mengenai variasi arsitektur Monolith:</strong></p><ul><li>A. Modular Monolith membagi kode ke dalam modul-modul terpisah namun tetap dalam satu proses deployment.</li><li>B. Distributed Monolith adalah sistem yang terdiri dari banyak layanan tetapi harus di-deploy secara bersamaan.</li><li>C. Single-Process Monolith selalu memiliki performa lebih buruk daripada Microservices.</li><li>D. Modular Monolith memungkinkan pengerjaan modul secara independen sebelum disatukan.</li><li>E. Distributed Monolith adalah tujuan akhir transisi dari Monolith ke Microservices.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Modular monolith terpisah secara logis (modul) tapi satu proses fisik. Distributed monolith adalah kondisi gagal di mana banyak layanan tapi coupling tinggi (deploy bersamaan).</li><li><strong>Salah (C):</strong> Monolith seringkali lebih performan karena tidak ada network latency.</li><li><strong>Salah (E):</strong> Distributed Monolith dianggap sebagai kegagalan penerapan SOA, bukan tujuan.</li></ul></details><hr><p><strong>6. Apa keuntungan tetap menggunakan atau memulai dengan arsitektur Monolith?</strong></p><ul><li>A. Topologi deployment yang jauh lebih sederhana.</li><li>B. Memudahkan code reuse tanpa perlu memisahkan library.</li><li>C. Skalabilitas granular pada fitur tertentu lebih mudah dilakukan dibanding Microservices.</li><li>D. Workflow pengembangan, monitoring, dan troubleshooting lebih sederhana.</li><li>E. Menghindari masalah konsistensi data terdistribusi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Semua adalah keuntungan Monolith yang disebut di dokumen.</li><li><strong>Salah (C):</strong> Skalabilitas granular (hanya membesarkan fitur tertentu) adalah keuntungan Microservices, bukan Monolith.</li></ul></details><hr><p><strong>7. Mengapa Distributed Monolith dianggap bermasalah meskipun sudah terdiri dari banyak layanan?</strong></p><ul><li>A. Karena gagal memenuhi janji SOA (Service Oriented Architecture).</li><li>B. Karena seluruh sistem tetap harus di-deploy secara bersamaan.</li><li>C. Karena menggunakan terlalu banyak teknologi berbeda (Polyglot).</li><li>D. Karena batas (boundaries) antar layanan terlalu longgar.</li><li>E. Karena seringkali menggabungkan kompleksitas sistem terdistribusi dengan kekakuan monolith.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Distributed monolith memiliki kompleksitas distribusi tapi tidak memiliki fleksibilitas deployment (harus deploy bareng).</li><li><strong>Salah (C):</strong> Masalahnya bukan pada teknologinya, tapi pada coupling-nya.</li></ul></details><hr><h2 id="bagian-3-keuntungan-microservices" tabindex="-1">Bagian 3: Keuntungan Microservices <a class="header-anchor" href="#bagian-3-keuntungan-microservices" aria-label="Permalink to &quot;Bagian 3: Keuntungan Microservices&quot;">​</a></h2><p><strong>8. Terkait Technology Heterogeneity, manakah implikasi positif yang valid?</strong></p><ul><li>A. Memungkinkan pemilihan alat yang tepat (right tool) untuk pekerjaan yang spesifik.</li><li>B. Mewajibkan setiap layanan ditulis dalam bahasa pemrograman yang berbeda-beda.</li><li>C. Memungkinkan penggunaan teknologi penyimpanan data (database) yang berbeda sesuai karakteristik data (misal: Graph DB untuk jejaring sosial).</li><li>D. Mengurangi biaya lisensi software secara keseluruhan.</li><li>E. Menghindari &quot;Technology Fetishism&quot;.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Bebas memilih bahasa/DB per layanan sesuai kebutuhan.</li><li><strong>Salah (B):</strong> &quot;Bisa&quot; berbeda bukan berarti &quot;wajib&quot; berbeda.</li><li><strong>Salah (D):</strong> Biaya lisensi justru sering naik (lebih banyak supporting software).</li><li><strong>Salah (E):</strong> Kebebasan teknologi justru berisiko menimbulkan &quot;Technology Fetishism&quot; (menggunakan teknologi baru tanpa alasan kuat), bukan menghindarinya.</li></ul></details><hr><p><strong>9. Bagaimana Microservices menangani Scaling (Penskalaan)?</strong></p><ul><li>A. Kita dapat melakukan scaling hanya pada layanan yang membutuhkan sumber daya lebih.</li><li>B. Bagian sistem yang lain dapat tetap berjalan pada perangkat keras yang lebih kecil/rendah.</li><li>C. Seluruh aplikasi diduplikasi ke banyak server seperti pada Monolith.</li><li>D. Menghilangkan kebutuhan akan Load Balancer.</li><li>E. Lebih efisien dalam penggunaan sumber daya dibanding scaling monolith untuk kasus beban tidak merata.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Targeted scaling adalah keuntungan utama.</li><li><strong>Salah (C):</strong> Itu cara scaling Monolith.</li><li><strong>Salah (D):</strong> Microservices justru sangat bergantung pada load balancing antar layanan.</li></ul></details><hr><p><strong>10. Apa maksud dari keuntungan Organizational Alignment dalam Microservices?</strong></p><ul><li>A. Memungkinkan arsitektur menyesuaikan struktur organisasi (tim kecil mengerjakan codebase kecil).</li><li>B. Mengurangi jumlah orang yang bekerja pada satu codebase yang sama.</li><li>C. Menghilangkan kebutuhan komunikasi antar tim (Backend, Frontend, DBA).</li><li>D. Meningkatkan produktivitas karena tim lebih otonom.</li><li>E. Memaksa semua tim untuk berada di satu lokasi fisik yang sama.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Tim kecil, kode kecil, produktivitas tinggi, meminimalkan konflik (&quot;delivery contention&quot;).</li><li><strong>Salah (C):</strong> Komunikasi tetap butuh, tapi batas kepemilikan lebih jelas.</li><li><strong>Salah (E):</strong> Justru membantu tim yang terdistribusi (distributed teams).</li></ul></details><hr><h2 id="bagian-4-pain-points-tantangan" tabindex="-1">Bagian 4: Pain Points (Tantangan) <a class="header-anchor" href="#bagian-4-pain-points-tantangan" aria-label="Permalink to &quot;Bagian 4: Pain Points (Tantangan)&quot;">​</a></h2><p><strong>11. Manakah tantangan nyata terkait Developer Experience saat beralih ke Microservices?</strong></p><ul><li>A. Runtime yang berat (seperti JVM) dapat membatasi jumlah layanan yang bisa dijalankan di laptop developer.</li><li>B. Developer harus memahami seluruh sistem secara mendalam sebelum bisa menulis satu baris kode.</li><li>C. Bahaya &quot;Technology Fetishism&quot; akibat terlalu banyaknya opsi teknologi baru.</li><li>D. Waktu build dan deploy lokal menjadi instan karena kode lebih kecil.</li><li>E. Kompleksitas mengelola banyak repositori dan konfigurasi lingkungan lokal.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Dokumen menyebutkan batasan resource lokal dan godaan teknologi baru. Opsi E adalah implikasi logis dari poin A.</li><li><strong>Salah (B):</strong> Microservices justru bertujuan agar dev hanya perlu paham layanan mereka (scope kecil).</li><li><strong>Salah (D):</strong> Meskipun kode kecil, orkestrasi lokal banyak layanan seringkali lambat/rumit.</li></ul></details><hr><p><strong>12. Masalah Reporting (Pelaporan) apa yang muncul pada arsitektur Microservices?</strong></p><ul><li>A. Data tersebar di banyak skema yang terisolasi secara logis.</li><li>B. Tidak bisa lagi melakukan join tabel sederhana antar domain bisnis yang berbeda.</li><li>C. Laporan harus dibuat dengan menggabungkan data dari berbagai sumber layanan.</li><li>D. Database menjadi terlalu besar (monolithic database) sehingga lambat di-query.</li><li>E. Hilangnya kemampuan untuk menyimpan data historis.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Karena &quot;Own their own state&quot;, data terpecah-pecah. Join tradisional SQL tidak bisa dilakukan lintas layanan.</li><li><strong>Salah (D):</strong> Justru database terpecah-pecah menjadi kecil.</li><li><strong>Salah (E):</strong> Data historis tetap bisa disimpan, hanya cara aksesnya yang lebih sulit.</li></ul></details><hr><p><strong>13. Tantangan Network Latency pada Microservices disebabkan oleh:</strong></p><ul><li>A. Proses yang sebelumnya lokal (in-process) kini harus melalui jaringan.</li><li>B. Kebutuhan untuk serialisasi dan deserialisasi data.</li><li>C. Penggunaan protokol komunikasi yang lebih lambat dibanding pemanggilan fungsi memori.</li><li>D. Jumlah panggilan jaringan yang meningkat drastis dibanding Monolith.</li><li>E. Penggunaan kabel jaringan fiber optik yang mahal.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, D</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Semua opsi A-D adalah penyebab teknis latensi yang disebut atau diimplikasikan dalam dokumen (distributed processing).</li><li><strong>Salah (E):</strong> Tidak relevan dengan arsitektur software.</li></ul></details><hr><p><strong>14. Mengapa aspek Testing (Pengujian) menjadi lebih sulit?</strong></p><ul><li>A. Cakupan tes End-to-End menjadi sangat luas dan besar.</li><li>B. Perlu menjalankan/men-deploy banyak proses layanan untuk skenario tes integrasi.</li><li>C. Tes unit tidak lagi bisa dilakukan pada level layanan individu.</li><li>D. Kesulitan mengonfigurasi lingkungan tes yang merepresentasikan sistem produksi.</li><li>E. Tidak adanya framework testing untuk sistem terdistribusi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Kompleksitas tes E2E dan konfigurasi lingkungan multi-servis adalah poin utama.</li><li><strong>Salah (C):</strong> Tes unit tetap bisa dan wajib dilakukan.</li><li><strong>Salah (E):</strong> Alat ada, tapi prosesnya yang sulit.</li></ul></details><hr><p><strong>15. Mengenai Data Consistency, manakah pernyataan yang benar?</strong></p><ul><li>A. Beralih dari sistem monolithic dengan satu database ke sistem terdistribusi menimbulkan tantangan konsistensi.</li><li>B. Transaksi ACID lintas layanan jauh lebih mudah diterapkan di Microservices.</li><li>C. Pengelola state tersebar di berbagai database yang berbeda.</li><li>D. Konsistensi data dijamin secara otomatis oleh protokol HTTP.</li><li>E. Penggunaan shared database adalah solusi yang disarankan untuk masalah ini.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Konsistensi menjadi sulit karena data tersebar.</li><li><strong>Salah (B):</strong> ACID lintas layanan sangat sulit (seringkali diganti Eventual Consistency).</li><li><strong>Salah (D):</strong> Protokol transport tidak menjamin konsistensi data bisnis.</li><li><strong>Salah (E):</strong> Dokumen melarang shared database (&quot;Microservices should avoid the use of shared databases&quot;).</li></ul></details><hr><h2 id="bagian-5-kasus-pengambilan-keputusan" tabindex="-1">Bagian 5: Kasus &amp; Pengambilan Keputusan <a class="header-anchor" href="#bagian-5-kasus-pengambilan-keputusan" aria-label="Permalink to &quot;Bagian 5: Kasus &amp; Pengambilan Keputusan&quot;">​</a></h2><p><strong>16. Sebuah perusahaan startup kecil dengan 3 developer ingin membangun aplikasi baru. Mengapa mereka disarankan untuk WASPADA atau menunda penggunaan Microservices?</strong></p><ul><li>A. Karena biaya awal (cost) infrastruktur dan operasional yang lebih tinggi.</li><li>B. Karena Microservices memperlambat proses di jangka pendek (kurva belajar, setup).</li><li>C. Karena Microservices tidak bisa berjalan di server murah.</li><li>D. Karena masalah organisasi (banyak orang, delivery contention) belum mereka alami.</li><li>E. Karena Monolith lebih sederhana untuk dipahami dan dioperasikan di awal.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Dokumen menekankan Microservices seringkali solusi masalah organisasi (banyak orang). Jika tim kecil, kompleksitasnya (Cost, Learning curve) tidak sebanding dengan manfaatnya.</li><li><strong>Salah (C):</strong> Microservices bisa berjalan di mana saja, tapi efisiensinya yang dipertanyakan untuk skala kecil.</li></ul></details><hr><p><strong>17. Dalam diagram Scope of Change (Cakupan Perubahan), manakah skenario yang menunjukkan buruknya Alignment of Architecture (misal: pada Layered Architecture)?</strong></p><ul><li>A. Perubahan fitur sederhana (misal: &quot;Show genre UI&quot;) memaksa perubahan di tiga tim berbeda (Frontend, Backend, DBA).</li><li>B. Logika bisnis tersebar di lapisan UI, Logika, dan Database.</li><li>C. Satu tim memiliki kendali penuh atas UI, Backend, dan Database untuk satu fitur (&quot;Profile functionality&quot;).</li><li>D. Perubahan pada UI tidak memerlukan perubahan pada skema database.</li><li>E. Tim dibentuk berdasarkan lapisan teknis (UI Team, Server Team), bukan fitur bisnis.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Skenario buruk adalah ketika perubahan kecil menyebar ke semua lapisan (coupling tinggi) dan tim terkotak-kotak secara teknis (bukan domain bisnis).</li><li><strong>Salah (C &amp; D):</strong> Ini adalah contoh baik (Microservices/Vertical Slice).</li></ul></details><hr><p><strong>18. Jika sebuah layanan (Service A) membutuhkan data dari layanan lain (Service B), apa pendekatan yang BENAR menurut prinsip Microservices dalam dokumen ini?</strong></p><ul><li>A. Service A melakukan query langsung ke database Service B.</li><li>B. Service A meminta data tersebut kepada Service B melalui antarmuka (interface) yang disediakan.</li><li>C. Service A dan Service B berbagi tabel database yang sama.</li><li>D. Service B mengirimkan data secara periodik ke database Service A (replikasi).</li><li>E. Service A membaca backup log dari Service B.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> &quot;If a microservice wants to access data held by another... it should go and ask that second microservice.&quot;</li><li><strong>Salah (A &amp; C):</strong> Melanggar prinsip Information Hiding dan Own Their Own State.</li><li><strong>Salah (D &amp; E):</strong> Tidak disebutkan sebagai pola standar akses data real-time dalam konteks dasar dokumen ini.</li></ul></details><hr><p><strong>19. Terkait Security (Keamanan), apa resiko tambahan yang harus dikelola di Microservices?</strong></p><ul><li>A. Data yang bergerak antar layanan (data in transit) lebih rentan disadap.</li><li>B. Perlu mengamankan lebih banyak endpoint agar hanya pihak berwenang yang bisa mengakses.</li><li>C. Kode program menjadi terbuka untuk umum (open source) secara otomatis.</li><li>D. Penggunaan HTTPS/TLS menjadi kurang penting karena komunikasi terjadi di jaringan internal.</li><li>E. Autentikasi antar layanan menjadi tantangan baru.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Karena komunikasi via jaringan, data in transit dan perlindungan endpoints menjadi krusial.</li><li><strong>Salah (C):</strong> Arsitektur tidak menentukan lisensi kode.</li><li><strong>Salah (D):</strong> Justru semakin penting, bahkan di internal (Zero Trust).</li></ul></details><hr><p><strong>20. Kapan keputusan untuk menggunakan Microservices dianggap tepat?</strong></p><ul><li>A. Ketika Anda ingin menyelesaikan masalah teknis murni, bukan masalah organisasi.</li><li>B. Ketika Anda perlu memungkinkan sejumlah besar orang bekerja pada sistem yang sama secara paralel.</li><li>C. Ketika Anda ingin meminimalkan latensi jaringan antar komponen.</li><li>D. Ketika kompleksitas mengelola Monolith sudah menghambat delivery speed dan rekrutmen.</li><li>E. Ketika Anda memiliki tim kecil yang ingin mencoba teknologi terbaru.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong></p><ul><li><strong>Benar:</strong> Dokumen menekankan: &quot;Microservices are very often a solution to an organizational problem&quot; (banyak orang, paralel) dan &quot;developer experience/recruiting&quot;.</li><li><strong>Salah (A):</strong> Dokumen menyangkal ini (&quot;rather than a technical one&quot;).</li><li><strong>Salah (C):</strong> Microservices menambah latensi.</li><li><strong>Salah (E):</strong> Alasan yang salah (Technology Fetishism).</li></ul></details>',85)])])}const p=n(t,[["render",l]]);export{k as __pageData,p as default};
